  background:
    linear-gradient(var(--arxiv-card-grey), var(--arxiv-card-grey)) padding-box,
    linear-gradient(to bottom, #ddd8d2, #b3ada4) border-box;
}
.ds-btn-secondary.on-tint:hover {
  background:
    linear-gradient(var(--arxiv-warm-wash), var(--arxiv-warm-wash)) padding-box,

