/* ═══════════════════════════════════════════════════════════════════════
   ELEMENT PILL  (.ds-element-pill)
   ───────────────────────────────────────────────────────────────────────
   Small white pill that floats anchored to a piece of content
   (an equation, a figure) to host action affordances for it. Used
   wherever arXiv adds metadata chrome (permalink, copy TeX, alt-text
   actions, etc.) that should live on the element rather than in a
   margin lane.

   The pill is `position: absolute`; the consumer is responsible for
   the positioning context (typically `position: relative` on the
   element's wrapper) and for the offset (typically `bottom: -14px;
   left: 50%; transform: translateX(-50%);` to straddle the element's
   bottom edge by ~50%).

   Hidden at rest. Add `.is-revealed` to the pill (or whatever class
   the consumer's hover/focus rule applies) to fade it in.

   Chips inside the pill are styled by the consumer — the pill itself
   only provides the floating-panel material.

   Validated 2026-05-27 in arxiv-mockups/arxiv-public/html-redesign.html
   (equation actions, figure actions — Distill-style anchored chrome).

   Example:
     <div class="eqn-wrap" style="position: relative;">
       <!-- equation here -->
       <div class="ds-element-pill" style="bottom: -14px; left: 50%; transform: translateX(-50%);">
         <button>View TeX</button>
         <button>Permalink</button>
         <button>Copy</button>
       </div>
     </div>
   ═══════════════════════════════════════════════════════════════════════ */

.ds-element-pill {
  position: absolute;
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 4px 14px;
  width: max-content;
  max-width: calc(100% - 16px);
  padding: 6px 14px;
  background: #ffffff;
  border: 1px solid var(--arxiv-pill-border);
  border-radius: 999px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.10);
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity 0.18s ease, visibility 0s linear 0.18s;
  z-index: 2;
}
.ds-element-pill.is-revealed {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transition: opacity 0.18s ease, visibility 0s linear 0s;
}


/* ═══════════════════════════════════════════════════════════════════════
   ALERT / STATUS MESSAGE  (.ds-alert)
   ───────────────────────────────────────────────────────────────────────
   Inline status banner — success / info / warning / error (failure).
   Token-driven via the --arxiv-{success,info,warning,error}-* families
   (see color-mapping.md "Status & alert colors — shared"). Structurally
   identical to the internal stylesheet's .ds-alert; only the token names
   differ (--arxiv- prefix here).

   Color is never the sole signal — pair each variant with a distinct icon
   shape AND a leading word (WCAG 1.4.1). ARIA: role="status" for
   success/info (polite), role="alert" for warning/error (assertive);
   icons carry aria-hidden="true". Inline links inherit the variant color
   and stay underlined, per the link policy.

   Promoted from arxiv-mockups/design-patterns/alert-styles.html (2026-05-28).

   Example:
     <div class="ds-alert ds-alert-info" role="status">
       <svg class="ds-alert-icon" aria-hidden="true">…</svg>
       <div class="ds-alert-content">
         <p class="ds-alert-title">Viewing an older version</p>
         <p>A newer version of this paper exists — <a href="...">see v3</a>.</p>
       </div>
     </div>
   ═══════════════════════════════════════════════════════════════════════ */

.ds-alert {
  display: flex;
  align-items: flex-start;
  gap: 11px;
  padding: 12px 14px;
  border: 1px solid;
  border-left-width: 4px;
  border-radius: 6px;
  font-family: var(--arxiv-font-sans);
  font-size: 13px;
  line-height: 1.5;
}
.ds-alert-icon {
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  margin-top: 1px;
  stroke: currentColor;
  fill: none;
}
.ds-alert-content { margin: 0; min-width: 0; }
.ds-alert-title { font-weight: 700; margin: 0 0 2px; }
.ds-alert-content p { margin: 0; }
.ds-alert a {
  color: inherit;
  font-weight: 600;
  text-decoration: underline;
  text-underline-offset: 2px;
}
.ds-alert-dismiss {
  flex-shrink: 0;
  margin-left: auto;
  margin-top: -2px;
  background: none;
  border: none;
  cursor: pointer;
  color: inherit;
  opacity: 0.7;
  padding: 2px;
  border-radius: 3px;
  line-height: 0;
  transition: opacity 0.15s ease;
}
.ds-alert-dismiss:hover { opacity: 1; }
.ds-alert-dismiss:focus-visible { outline: 3px solid var(--arxiv-focus-ring); outline-offset: 2px; }
.ds-alert-dismiss svg { width: 16px; height: 16px; stroke: currentColor; fill: none; }

/* Variants — bg + border + fg (icon uses currentColor = fg) */
.ds-alert-success { background: var(--arxiv-success-bg); border-color: var(--arxiv-success-border); color: var(--arxiv-success-fg); }
.ds-alert-info    { background: var(--arxiv-info-bg);    border-color: var(--arxiv-info-border);    color: var(--arxiv-info-fg); }
.ds-alert-warning { background: var(--arxiv-warning-bg); border-color: var(--arxiv-warning-border); color: var(--arxiv-warning-fg); }
.ds-alert-error   { background: var(--arxiv-error-bg);   border-color: var(--arxiv-error-border);   color: var(--arxiv-error-fg); }

/* Dark mode — overrides the status tokens only. This is the first
   dark-aware block in the public stylesheet; broader public dark mode is
   still pending (color-mapping.md open question). Guarded by data-theme
   so a page can lock to light with <html data-theme="light">. */
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --arxiv-link-blue:       #64b5f6;  /* 7.84:1 on Repository Brown ✓ AAA */
    --arxiv-link-hover:      #90caf9;
    --arxiv-link-visited:    #c084e0;  /* 6.30:1 on Repository Brown ✓ AA */
    --arxiv-success-bg:      #1e2b0d;
    --arxiv-success-border:  #8fbd3a;
    --arxiv-success-fg:      #c5e1a5;  /* 10.4:1 ✓ AAA */
    --arxiv-info-bg:         #132433;
    --arxiv-info-border:     #64b5f6;
    --arxiv-info-fg:         #90caf9;  /* 9.0:1 ✓ AAA */
    --arxiv-warning-bg:      #2e2410;
    --arxiv-warning-border:  #e8b800;
    --arxiv-warning-fg:      #ffe082;  /* 11.8:1 ✓ AAA */
    --arxiv-error-bg:        #2d1414;
    --arxiv-error-border:    #e57373;
    --arxiv-error-fg:        #ef9a9a;  /* 8.0:1 ✓ AAA */
  }
